import { Component, Element, Prop, State, h } from '@stencil/core';

@Component({
  tag: 'std-collapse',
  styleUrl: 'std-collapse.css',
  shadow: true
})
export class StdCollapseComponent {
  @Prop() label: string;
  @Prop() link: string;
  @Prop() labelLink: string;
  @Prop() disabled: boolean;
  @Prop() isOverflow: boolean = false;
  @Prop() classes: string;
  @Prop() hasContent: boolean = false;
  @State() isOpen: boolean;
  @Element() el: HTMLElement;

  toggleCollapse(): void {
    this.isOpen = !this.isOpen;

    const body = this.el.shadowRoot.querySelector('.css-collapse-body') as HTMLElement;
    body.style.maxHeight = this.isOpen ? `${body.scrollHeight}px` : '0px';
  }

  render() {
    const collapseClasses = ['css-collapse js-collapse border-t border-b border-alternative-medium bg-white w-full', this.isOpen ? 'is-open' : '', this.classes]
      .join(' ')
      .trim()
      .replace(/\s+/g, ' ');

    return (
      <div class="pa-0 ma-0">
        {this.hasContent && <slot />}
        {!this.hasContent && (
          <div class={collapseClasses}>
            <div class="css-collapse-header js-collapse-header h-14 py-4 w-full">
              <div class="flex items-center justify-between gap-2 w-full cursor-pointer" onClick={() => this.toggleCollapse()}>
                <p class="font-bold text-dark whitespace-nowrap">{this.label}</p>
                <div class="flex justify-end gap-4">
                  {this.link && <std-link label={this.labelLink} disabled={this.disabled}></std-link>}
                  <i class={`icon-chevron-down text-2xl leading-none text-dark  ${this.isOpen ? 'rotate-180' : ''} `}></i>
                </div>
              </div>
            </div>
            <div class={`css-collapse-body js-collapse-body ${this.isOverflow ? ' overflow-visible ' : ' overflow-hidden'}`}>
              <slot />
            </div>
          </div>
        )}
      </div>
    );
  }
}
